import Link from "next/link";
import { requireSuperAdmin } from "@/src/modules/authorization/server/require-super-admin";
import { getVendorBundle } from "@/src/modules/vendors/server/repository";
export const dynamic = "force-dynamic";
export default async function VendorReview({ params, searchParams }: { params: Promise<{ vendorId: string }>; searchParams: Promise<{ updated?: string }> }) { await requireSuperAdmin(); const [{ vendorId }, query] = await Promise.all([params, searchParams]); const { vendor, business, compliance, store, documents, events } = await getVendorBundle(vendorId); return <main className="admin-detail"><header><div><p className="kicker">VENDOR DUE DILIGENCE</p><h1>{String(business.legalName)}</h1></div><Link href="/admin/vendors">Back to queue</Link></header>{query.updated && <p className="success-note">Review decision recorded.</p>}<section className="review-summary"><article><span>Status</span><strong>{String(vendor.status).replaceAll("_", " ")}</strong></article><article><span>Vendor type</span><strong>{String(compliance?.vendorType ?? "—").replaceAll("_", " ")}</strong></article><article><span>Registration</span><strong>{String(business.registrationNumber)}</strong></article><article><span>Country</span><strong>{String(business.countryCode)}</strong></article><article><span>Store</span><strong>{String(store?.name ?? "—")}</strong></article><article><span>Bank</span><strong>{String(compliance?.bankName ?? "—")}</strong></article><article><span>Account name</span><strong>{String(compliance?.bankAccountName ?? "—")}</strong></article><article><span>Compliance</span><strong>{String(compliance?.complianceStatus ?? "—")}</strong></article><article className="wide"><span>Registered address</span><strong>{String(business.address)}</strong></article><article className="wide"><span>Operational address</span><strong>{String(compliance?.operationalAddress ?? "—")}</strong></article><article className="wide"><span>Directors / beneficial owners</span><strong>{[...(Array.isArray(compliance?.directors) ? compliance.directors : []), ...(Array.isArray(compliance?.beneficialOwners) ? compliance.beneficialOwners : [])].join(", ") || "—"}</strong></article></section><section className="document-list"><h2>Submitted documents</h2>{documents.map((document) => <article key={document.$id}><div><strong>{String(document.documentType).replaceAll("_", " ")}</strong><p>{String(document.filename)} · {Math.ceil(Number(document.sizeBytes) / 1024)} KB</p></div><a href={`/api/admin/vendor-documents/${document.$id}`} target="_blank" rel="noreferrer">Open securely</a></article>)}</section><form className="review-form" method="post" action={`/api/admin/vendors/${vendorId}/review`}><label>Review notes<textarea name="notes" placeholder="Record the reason and follow-up requirements" required /></label><div><button name="action" value="approve">Approve vendor</button><button name="action" value="request_information">Request information</button><button className="danger" name="action" value="reject">Reject</button></div></form>{events.length > 0 && <section className="review-history"><h2>Review history</h2>{events.map((event) => <p key={event.$id}><strong>{String(event.action).replaceAll("_", " ")}</strong> · {new Date(String(event.occurredAt)).toLocaleString("en-GB")}<br />{String(event.notes ?? "No notes")}</p>)}</section>}</main>; }
